// Факториал: n! = n × (n-1) × (n-2) × ... × 1
function factorial(n) {
  // БАЗОВЫЙ СЛУЧАЙ: 0! = 1, 1! = 1
  if (n <= 1) {
    return 1;  // стоп! больше не вызываем себя
  }
  // РЕКУРСИВНЫЙ ШАГ: n! = n × (n-1)!
  return n * factorial(n - 1);  // вызываем себя с меньшим n
}

// factorial(3):
// 1. n = 3, 3 > 1 → 3 * factorial(2)
// 2. n = 2, 2 > 1 → 2 * factorial(1)
// 3. n = 1, 1 <= 1 → return 1 (базовый случай!)
// 4. Раскрутка: 2 * 1 = 2, затем 3 * 2 = 6
console.log(factorial(3));  // 6

