// Как стек вызовов выглядит для factorial(3):
// Вызов 1: factorial(3)
//   Вызов 2: factorial(2)
//     Вызов 3: factorial(1)  ← БАЗОВЫЙ СЛУЧАЙ
//   Возврат: 1
// Возврат: 2 * 1 = 2
// Возврат: 3 * 2 = 6

function factorial(n) {
  if (n <= 1) return 1;  // базовый случай
  return n * factorial(n - 1);  // шаг
}
console.log(factorial(3));  // 6

function fib(n) {
  // Базовые случаи: F(0) = 0, F(1) = 1
  if (n <= 0) return 0;
  if (n === 1) return 1;
  // Шаг: F(n) = F(n-1) + F(n-2)
  return fib(n - 1) + fib(n - 2);
}

console.log(fib(6));  // 8
console.log(fib(10)); // 55

// fib(5) создаёт дерево вызовов:
//    fib(5)
//   /      \
// fib(4)   fib(3)
// /    \   /    \
// fib(3) fib(2) fib(2) fib(1)
// ... и так далее — много повторений

