// Опасно: базовый случай недостижим
function infinite() {
  infinite();  // нет условия остановки!
}
// infinite();  // RangeError: Maximum call stack size exceeded

// Опасно: n слишком большое
function factorialBig(n) {
  if (n <= 1) return 1;
  return n * factorialBig(n - 1);
}
// factorialBig(100000);  // RangeError! Глубина > 10000

// Безопасно: небольшая глубина
console.log(factorialBig(10));  // 3628800

// Рекурсия: чистая, но медленнее и риск стека
function sumRecursive(n) {
  if (n <= 0) return 0;
  return n + sumRecursive(n - 1);
}

// Цикл: быстрее, безопаснее, но более многословно
function sumLoop(n) {
  let sum = 0;
  for (let i = 1; i <= n; i++) {
    sum += i;
  }
  return sum;
}

// Для дерева лучше рекурсия:
function printTree(node) {
  console.log(node.name);       // печатаем текущий узел
  for (const child of node.children) {
    printTree(child);           // рекурсивно обходим дочерние
  }
}

function sumArray(arr) {
  // Базовый случай: пустой массив
  if (arr.length === 0) {
    return 0;
  }
  // Шаг: первый элемент + сумма остальных
  return arr[0] + sumArray(arr.slice(1));
  // arr[0] — первый элемент
  // arr.slice(1) — массив без первого элемента
}

console.log(sumArray([1, 2, 3, 4, 5]));  // 15
// 1 + sumArray([2,3,4,5])
// 1 + 2 + sumArray([3,4,5])
// 1 + 2 + 3 + sumArray([4,5])
// 1 + 2 + 3 + 4 + sumArray([5])
// 1 + 2 + 3 + 4 + 5 + sumArray([])
// 1 + 2 + 3 + 4 + 5 + 0 = 15

// ПЕРЕД рекурсией: от 3 к 1
function countdown(n) {
  if (n <= 0) return;
  console.log(n);       // сначала выводим
  countdown(n - 1);     // потом вызываем
}
countdown(3);  // 3, 2, 1

// ПОСЛЕ рекурсии: от 1 к 3
function countup(n) {
  if (n <= 0) return;
  countup(n - 1);       // сначала вызываем
  console.log(n);       // потом выводим (при раскрутке)
}
countup(3);  // 1, 2, 3

function power(base, exp) {
  // Базовый случай: любое число в степени 0 = 1
  if (exp === 0) {
    return 1;
  }
  // Шаг: base^exp = base × base^(exp-1)
  return base * power(base, exp - 1);
}

console.log(power(2, 5));  // 32
console.log(power(3, 3));  // 27
// power(2, 5) = 2 * power(2, 4)
//             = 2 * 2 * power(2, 3)
//             = 2 * 2 * 2 * power(2, 2)
//             = 2 * 2 * 2 * 2 * power(2, 1)
//             = 2 * 2 * 2 * 2 * 2 * power(2, 0)
//             = 2 * 2 * 2 * 2 * 2 * 1 = 32

